INSERT INTO site (id, content) VALUES (1, '{"brand":"Studio Name","metaTitle":"Studio Name | Video for Brands","metaDescription":"Videographer and photographer making campaign films, restaurant stories and brand videos. Based in Athens, working worldwide.","categories":[{"id":"cafe","label":"Cafes"},{"id":"product","label":"Products"}],"hero":{"line1":"Films that make","line2":"brands feel real.","sub":"Video for cafes, fashion labels, restaurants and the people behind them.","film":"troufa-walking","reel":"troufa-coffee-day"},"story":{"films":["troufa-coffee-day","amabile-cubes","amabile-lights","amabile-candles"]},"gallery":{"title":"More films","films":["amabile-boat","troufa-walking","amabile-lights","troufa-coffee-day","amabile-candles","amabile-cubes"]},"services":{"title":"What I make","items":[{"title":"Campaign and product films","text":"Short films for a launch, a collection or a season, planned with you from the idea to the final cut. You get one hero film and shorter cuts for social."},{"title":"Cafes, restaurants and venues","text":"Video that shows the food, the room and the people, made for your website, your menu screens and your ads."},{"title":"Social video and reels","text":"Vertical and square edits made to be posted, with the sizes and captions each platform needs."}],"note":"Every project starts with a short call and a written quote.","noteLink":"Tell me what you need"},"about":{"heading":"Hi, I''m Name.","paragraphs":["I''m a videographer and photographer based in Athens. For the past X years I''ve worked with clothing brands and restaurants that want their videos to look like them, not like everyone else.","I work on my own or with a small crew, depending on the job. You get a clear quote, a shot list agreed in advance and finished files on time."],"film":"amabile-boat"},"clients":{"title":"What clients say","quotes":[{"quote":"Replace this with a short quote from a client: one or two sentences about working together.","name":"Client name, role, company"},{"quote":"Replace this with a short quote from a client: what they asked for and what they got.","name":"Client name, role, company"},{"quote":"Replace this with a short quote from a client: how it was to work with you.","name":"Client name, role, company"}]},"contact":{"heading":"Have a project in mind?","lead":"Tell me what you''re making and when you need it. I reply within two working days.","email":"hello@yourdomain.com","phone":"+30 000 000 0000","instagram":"https://instagram.com/","vimeo":"https://vimeo.com/","formAction":"https://formspree.io/f/YOUR_FORM_ID"}}');
